select rownum,a.* from (SELECT T5.SEQ_NO SEQ_NO, T5.SETTLE_TIME SETTLE_TIME, T5.OPER_TYPE OPER_TYPE, T1.SETTLE_SEQ_NO SETTLE_SEQ_NO, T1.SETTLE_STATUS settleStatus, T1.ORDER_ID orderId, T1.TRADE_ID tradeId, T1.TRADE_DATE tradeDate, T1.SETTLE_DATE settleDate, T1.PORTFOLIO_ID portfolioId, concat(concat(sci.BUSI_ACCT_NO,':'),sci.ACCT_NAME) acctNo, concat(concat(ssai.SEC_ACCT_ID,':'),ssai.SEC_ACCT_NAME) secAcctId, T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.FINPROD_ID finprodId, T1.PRIN prin, CASE WHEN etr.FINPROD_TYPE2 != 'F01' THEN T1.M_TRADE_AMT ELSE NULL END mTradeAmt, T1.PLEDGE_NUMBER pledgeNumber, CASE WHEN etr.FINPROD_TYPE2 != 'F01' THEN T1.PLEDGE_ID ELSE NULL END pledgeId, CASE WHEN etr.FINPROD_TYPE2 != 'F01' THEN T1.B_PLEDGE_ID ELSE NULL END bPledgeId, CASE WHEN etr.FINPROD_TYPE2 != 'F01' THEN F1.FINPROD_ABBR ELSE NULL END pledgeName, CASE WHEN etr.FINPROD_TYPE2 != 'F01' THEN F1.FINPROD_MARKET_ID ELSE NULL END pledgeIdAbbr, CASE WHEN etr.FINPROD_TYPE2 != 'F01' THEN F2.FINPROD_MARKET_ID ELSE NULL END bPledgeIdAbbr, T1.BUSI_TYPE busiType, T1.COUNTER_ID counterId, T1.ENTRUST_NO entrustNo, CASE WHEN etr.FINPROD_TYPE2 = 'F01' THEN T2.FINPROD_MARKET_ID ELSE NULL END finprodMarketId, CASE WHEN etr.FINPROD_TYPE2 = 'F01' THEN T2.FINPROD_ABBR ELSE NULL END finprodName, CASE WHEN etr.FINPROD_TYPE2 = 'F01' THEN T1.SETTLE_NUM ELSE NULL END settleNum, CASE WHEN etr.FINPROD_TYPE2 = 'F01' THEN T1.SETTLE_AMT ELSE NULL END settleAmt, T3.PORTFOLIO_NAME portfolioName, T4.COUNTER_NAME counterName, T1.DEAL_NO dealNo, T6.REAL_NAME operator, decode( T1.SETTLE_STATUS,'01',1,'02',3,'03',2,'04',4) sort FROM TRD_MANUAL_SETTLE_INFO T1 LEFT JOIN ETR_ENTRUST etr ON T1.ENTRUST_NO = etr.ENTRUST_ID LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T3 ON T1.PORTFOLIO_ID = T3.PORTFOLIO_ID Left join MST_COUNTER_PARTY T4 ON T4.COUNTER_ID = T1.COUNTER_ID LEFT JOIN STL_CAPACCT_INFO sci ON T1.ACCT_NO = sci.ACCT_NO LEFT JOIN STL_SEC_ACCT_INFO ssai ON T1.SEC_ACCT_ID = ssai.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT F1 ON T1.PLEDGE_ID = F1.FINPROD_ID LEFT JOIN FIN_PRODUCT F2 ON T1.B_PLEDGE_ID = F2.FINPROD_ID left join TRD_MANUAL_SETTLE_FLOW T5 on T5.SETTLE_SEQ_NO = T1.SETTLE_SEQ_NO LEFT JOIN SYS_USER T6 ON T5.UPDATE_USER = T6.USER_NAME
AND T1.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userName})
AND ( T1.PORTFOLIO_ID IN
#{item}
OR T1.PORTFOLIO_ID IN
#{item}
)
and T1.TRADE_MARKET =#{tradeMarket}
and T1.FINPROD_ID like CONCAT('%',CONCAT(#{finprodMarketId}, '%'))
and T1.SETTLE_STATUS =#{settleStatus}
and T1.BUSI_TYPE =#{busiType}
and T1.TRADE_DATE >= to_date(#{tradeDateStart}, 'yyyy-MM-dd')
and T1.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and T1.SETTLE_DATE >= to_date(#{settleDateStart}, 'yyyy-MM-dd')
and T1.SETTLE_DATE <= to_date(#{settleDateEnd}, 'yyyy-MM-dd')
order by sort,T1.SETTLE_SEQ_NO,T1.UPDATE_TIME desc)a

select

from INF_CONTRACT_DETAILFILE
where DEAL_NO = #{param2} and ENTRUST_ID = #{param1}

SELECT PORTFOLIO_ID,HODING_TYPE,SEC_ACCT_ID,FINPROD_ID,INV_AIM,CDATE,BRANCH,SUM(NVL(AMOUNT,0)) AMOUNT
FROM PTL_SEC_POSITION_FLOW WHERE TRADE_ID = #{tradeId}
GROUP BY PORTFOLIO_ID,HODING_TYPE,SEC_ACCT_ID,FINPROD_ID,INV_AIM,CDATE,BRANCH

SELECT PORTFOLIO_ID,ACCT_ID,HODING_TYPE,CDATE,CCY,sum(AMOUNT) AMOUNT
FROM PTL_CASH_POSITION_FLOW WHERE ORDER_ID = #{orderId}
GROUP BY PORTFOLIO_ID,ACCT_ID,HODING_TYPE,CDATE,CCY

SELECT PORTFOLIO_ID,SEC_ACCT_ID,FINPROD_ID,INV_AIM,HODING_TYPE,CDATE,BRANCH,SUM(AMOUNT) AMOUNT
FROM ETR_SEC_POSITION_FLOW WHERE TRADE_ID = #{tradeId}
GROUP BY PORTFOLIO_ID,SEC_ACCT_ID,FINPROD_ID,INV_AIM,HODING_TYPE,CDATE,BRANCH

SELECT PORTFOLIO_ID,ACCT_ID,HODING_TYPE,CDATE,CCY,SUM(NVL(AMOUNT, 0)) AMOUNT
FROM ETR_CASH_POSITION_FLOW WHERE ORDER_ID = #{orderId}
GROUP BY PORTFOLIO_ID,ACCT_ID,HODING_TYPE,CDATE,CCY

